<?php
namespace App\Jobs;use App\Models\MediaAsset;use App\Services\Face\FaceRecognitionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Queue\Middleware\WithoutOverlapping;
class IndexFaceAsset implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int$tries=4;public int$timeout=180;public function __construct(public int$assetId){$this->onQueue('media-default');}public function backoff():array{return[15,60,240];}public function middleware():array{return[(new WithoutOverlapping('face-index-'.$this->assetId))->expireAfter(240)->dontRelease()];}public function handle(FaceRecognitionManager$m):void{$asset=MediaAsset::findOrFail($this->assetId);if(!$asset->group->face_recognition_enabled)return;$m->index($asset);}}
